// This code has been fully generated by an AI.

// Package web serves the my Velo panel behind the Home Assistant ingress proxy.
//
// All links, scripts and API calls use relative URLs. Together with
// <base href> derived from X-Ingress-Path this keeps the UI working under the
// dynamic ingress prefix as well as on a plain local port.
package web

import (
	"embed"
	"encoding/json"
	"html/template"
	"io/fs"
	"log/slog"
	"net/http"
	"time"
)

//go:embed templates/*.html
var templateFS embed.FS

//go:embed static
var staticFS embed.FS

// Info describes the running instance for the status page and health endpoint.
type Info struct {
	Version     string
	StartedAt   time.Time
	MapProvider string
	MapKeySet   bool
}

// NewHandler returns the HTTP handler with all panel routes.
func NewHandler(info Info, logger *slog.Logger) http.Handler {
	tmpl := template.Must(template.ParseFS(templateFS, "templates/*.html"))
	static, err := fs.Sub(staticFS, "static")
	if err != nil {
		panic(err)
	}

	mux := http.NewServeMux()
	mux.Handle("GET /static/", http.StripPrefix("/static/", http.FileServerFS(static)))

	mux.HandleFunc("GET /api/health", func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Content-Type", "application/json")
		_ = json.NewEncoder(w).Encode(map[string]any{
			"status":       "ok",
			"version":      info.Version,
			"uptime_s":     int(time.Since(info.StartedAt).Seconds()),
			"base_path":    BasePath(r),
			"map_provider": info.MapProvider,
			"map_key_set":  info.MapKeySet,
		})
	})

	mux.HandleFunc("GET /{$}", func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Content-Type", "text/html; charset=utf-8")
		data := struct {
			Info
			BasePath string
			Ingress  bool
		}{info, BasePath(r), r.Header.Get(HeaderIngressPath) != ""}
		if err := tmpl.ExecuteTemplate(w, "index.html", data); err != nil {
			logger.Error("render index", "err", err)
		}
	})

	return logRequests(logger, mux)
}

func logRequests(logger *slog.Logger, next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		start := time.Now()
		next.ServeHTTP(w, r)
		logger.Debug("request", "method", r.Method, "path", r.URL.Path, "duration", time.Since(start))
	})
}
